import json
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def parse_date(date_str):
    """Parse date string in YYYYMMDD format to datetime.date object."""
    if not date_str or date_str.strip() == "":
        return None
    try:
        return datetime.strptime(date_str.strip(), "%Y%m%d").date()
    except ValueError:
        return None

def load_fda_data(packet_dir):
    """Load FDA enforcement reports data from JSON file."""
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    with open(file_path, 'r') as f:
        data = json.load(f)

    # Create a mapping from recall_number to the record
    records = {}
    for record in data.get("results", []):
        recall_num = record.get("recall_number", "")
        if recall_num:
            records[recall_num] = record
    return records

def extract_fact_value(record, fact_name, rule_id):
    """Extract fact value from record based on fact name and rule."""
    if fact_name == "initiation date":
        date_str = record.get("recall_initiation_date", "")
        return parse_date(date_str)
    elif fact_name == "classification date":
        date_str = record.get("center_classification_date", "")
        return parse_date(date_str)
    elif fact_name == "termination date":
        date_str = record.get("termination_date", "")
        return parse_date(date_str)
    return None

def process_pair(pair, facts, fda_records):
    """Process a single pair (rule_id::entity) and return fact values."""
    rule_id, entity = pair.split("::", 1)
    result = {}

    if entity not in fda_records:
        # Entity not found in records
        for fact_name in facts[rule_id]:
            result[fact_name] = "ABSENT"
        return result

    record = fda_records[entity]
    fact_values = {}

    # Extract all fact values for this entity
    for fact_name in facts[rule_id]:
        value = extract_fact_value(record, fact_name, rule_id)
        fact_values[fact_name] = value

    # Check for conflicts (multiple records with same recall number not expected here)
    # Since we have single record per recall number, no conflict in this dataset
    for fact_name in facts[rule_id]:
        value = fact_values[fact_name]
        if value is None:
            result[fact_name] = "ABSENT"
        else:
            # Format date as YYYY-MM-DD
            formatted_date = value.strftime("%Y-%m-%d")
            result[fact_name] = [formatted_date, "fda_enforcement_reports"]

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    # Load FDA data
    fda_records = load_fda_data(packet_dir)

    # Process all pairs
    output = {}
    for pair in manifest["pairs"]:
        output[pair] = process_pair(pair, manifest["facts"], fda_records)

    # Print JSON output
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
