import json
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def parse_date(date_str):
    """Parse date string in YYYYMMDD format to datetime.date, handling empty/missing."""
    if not date_str or date_str.strip() == "":
        return None
    try:
        return datetime.strptime(date_str.strip(), "%Y%m%d").date()
    except ValueError:
        return None

def load_fda_reports(packet_dir):
    """Load FDA enforcement reports from JSON file."""
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    with open(file_path, 'r', encoding='utf-8') as f:
        data = json.load(f)
    return data.get("results", [])

def find_recall_by_number(reports, recall_number):
    """Find all report entries matching a recall number."""
    return [r for r in reports if r.get("recall_number") == recall_number]

def extract_fact_value(report, fact_name, rule_id):
    """Extract fact value from a report based on fact name and rule."""
    if rule_id == "fda.classified_30d":
        if fact_name == "initiation date":
            return report.get("recall_initiation_date")
        elif fact_name == "classification date":
            return report.get("center_classification_date")
    elif rule_id == "fda.terminated_180d":
        if fact_name == "initiation date":
            return report.get("recall_initiation_date")
        elif fact_name == "termination date":
            return report.get("termination_date")
    return None

def process_pair(pair, reports, facts):
    """Process a single rule_id::entity pair."""
    rule_id, entity = pair.split("::", 1)
    matching_reports = find_recall_by_number(reports, entity)

    result = {}
    for fact_name in facts[rule_id]:
        values = []
        sources = []

        for report in matching_reports:
            value = extract_fact_value(report, fact_name, rule_id)
            if value is not None:
                values.append(value)
                sources.append("fda_enforcement_reports")

        if not values:
            result[fact_name] = "ABSENT"
        elif len(set(values)) == 1:
            # All values agree
            result[fact_name] = [values[0], sources[0]]
        else:
            # Conflicting values
