import json
import os
import sys
from datetime import datetime
from typing import Dict, List, Any, Optional, Tuple

def parse_date(date_str: str) -> Optional[datetime]:
    """Parse date string in various formats to datetime object."""
    if not date_str or date_str.strip() == "":
        return None

    # Remove any whitespace
    date_str = date_str.strip()

    # Try common formats
    formats = ["%Y%m%d", "%Y-%m-%d", "%m/%d/%Y", "%d/%m/%Y"]

    for fmt in formats:
        try:
            return datetime.strptime(date_str, fmt)
        except ValueError:
            continue

    return None

def format_date(date_obj: Optional[datetime]) -> Optional[str]:
    """Format datetime object to YYYY-MM-DD string."""
    if date_obj is None:
        return None
    return date_obj.strftime("%Y-%m-%d")

def load_fda_data(packet_dir: str) -> Dict[str, Dict[str, Any]]:
    """Load FDA enforcement reports data."""
    file_path = os.path.join(packet_dir, "fda_enforcement_reports.json")
    with open(file_path, 'r', encoding='utf-8') as f:
        data = json.load(f)

    # Create mapping from recall_number to record
    records = {}
    for record in data.get("results", []):
        recall_num = record.get("recall_number", "")
        if recall_num:
            records[recall_num] = record

    return records

def extract_fact_value(record: Dict[str, Any], fact_name: str, rule_id: str) -> Tuple[Optional[str], Optional[str]]:
    """Extract fact value from record based on fact name and rule."""
