        if fact_name == "initiation date":
            value = record.get("recall_initiation_date")
            doc = "fda_enforcement_reports"
        elif fact_name == "classification date":
            value = record.get("center_classification_date")
            doc = "fda_enforcement_reports"
        else:
            return None, None

    elif rule_id == "fda.terminated_180d":
        if fact_name == "initiation date":
            value = record.get("recall_initiation_date")
            doc = "fda_enforcement_reports"
        elif fact_name == "termination date":
            value = record.get("termination_date")
            doc = "fda_enforcement_reports"
        else:
            return None, None

    else:
        return None, None

    # Clean up the value
    if value is not None:
        value = value.strip()
        if value == "" or value == "N/A":
            value = None

    return value, doc

def process_pair(pair: str, fda_records: Dict[str, Dict[str, Any]], 
                 facts_map: Dict[str, List[str]]) -> Dict[str, Any]:
    """Process a single rule::entity pair."""
    rule_id, entity = pair.split("::", 1)

    # Get the record for this entity
    record = fda_records.get(entity)

    if not record:
        # Entity not found in records
        result = {}
        for fact_name in facts_map[rule_id]:
            result[fact_name] = "ABSENT"
        return result

