import json
import os
import sys
from datetime import datetime
from pathlib import Path

def parse_date(date_str):
    """Parse date string in YYYYMMDD format to datetime object."""
    if not date_str or date_str.strip() == "":
        return None
    try:
        return datetime.strptime(date_str.strip(), "%Y%m%d")
    except ValueError:
        return None

def date_to_iso(date_obj):
    """Convert datetime object to YYYY-MM-DD string."""
    if date_obj:
        return date_obj.strftime("%Y-%m-%d")
    return None

def load_fda_data(packet_dir):
    """Load FDA enforcement reports from JSON file."""
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    with open(file_path, 'r') as f:
        data = json.load(f)
    return data.get("results", [])

def extract_facts_for_entity(records, entity_id, rule_facts):
    """Extract facts for a specific entity (recall number) based on rule facts."""
    facts = {}

    # Filter records for this recall number
    entity_records = [r for r in records if r.get("recall_number") == entity_id]

    if not entity_records:
        # No records found for this entity
        for fact in rule_facts:
            facts[fact] = "ABSENT"
        return facts

    # For each fact, collect values from all records
    fact_values = {}
    for fact in rule_facts:
        fact_values[fact] = []

    for record in entity_records:
        # Map fact names to field names based on decision rules
        if "initiation date" in rule_facts:
            value = record.get("recall_initiation_date")
            if value:
                fact_values["initiation date"].append((value, "fda_enforcement_reports"))

        if "classification date" in rule_facts:
            value = record.get("center_classification_date")
            if value:
                fact_values["classification date"].append((value, "fda_enforcement_reports"))

        if "termination date" in rule_facts:
            value = record.get("termination_date")
            if value:
                fact_values["termination date"].append((value, "fda_enforcement_reports"))

    # Determine final value for each fact
    for fact in rule_facts:
        values = fact_values[fact]

        if not values:
            facts[fact] = "ABSENT"
        else:
            # Check if all values are the same
            unique_values = set(v[0] for v in values)
            if len(unique_values) == 1:
                # All values agree
                value_str = list(unique_values)[0]
                date_obj = parse_date(value_str)
                if date_obj:
                    facts[fact] = [date_to_iso(date_obj), "fda_enforcement_reports"]
                else:
                    # Invalid date format
                    facts[fact] = "ABSENT"
            else:
                # Conflicting values
                facts[fact] = "CONFLICT"

    return facts

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    # Load FDA data
    fda_records = load_fda_data(packet_dir)

    # Process each pair
    result = {}
    for pair in manifest["pairs"]:
        rule_id, entity_id = pair.split("::")
        rule_facts = manifest["facts"][rule_id]

        facts = extract_facts_for_entity(fda_records, entity_id, rule_facts)
        result[pair] = facts

    # Output result as JSON
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()
